lib='''from collections import Counter

def colors(grid):
    """Counter of cell values in the grid."""
    return Counter(v for row in grid for v in row)

def background(grid):
    """The most common color in the grid."""
    return colors(grid).most_common(1)[0][0]

def cells_of(grid, value):
    """List of (row, col) positions of every cell equal to value."""
    return [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row) if v == value]

def bbox(cells):
    """(top, bottom, left, right) bounding box of a list of (row, col) cells."""
    rows = [i for i, j in cells]; cols = [j for i, j in cells]
    return min(rows), max(rows), min(cols), max(cols)

def fill_rect_rows(grid, mark, fill):
    """Draw the bounding-box rectangle of the mark color in fill color on background cells, and fill every interior row containing an interior mark with fill on background cells; marks keep their color, cells outside the rectangle are unchanged."""
    bg = background(grid)
    top, bot, left, right = bbox(cells_of(grid, mark))
    out = [row[:] for row in grid]
    for j in range(left, right + 1):
        for i in (top, bot):
            if out[i][j] == bg:
                out[i][j] = fill
    for i in range(top, bot + 1):
        if out[i][left] == bg:
            out[i][left] = fill
        if out[i][right] == bg:
            out[i][right] = fill
    for i in range(top + 1, bot):
        if any(grid[i][j] == mark for j in range(left + 1, right)):
            for j in range(left + 1, right):
                if out[i][j] == bg:
                    out[i][j] = fill
    return out
